---Init
---初始化地图
function MazeMapMgr:Init()
    self.pointPar = GameObject.Find("Points").transform
    self.mazeCam = GameObject.Find("MazeCamera").transform:GetComponent("Camera")
end

--摄像机和人物的默认距离
function MazeMapMgr:SetPlayerDis(playerPar)
    if not playerPar or not self.mazeCam then 
        self.playerDis = Vector3(0, 0, 0)
        return
    end
    local camPos = self.mazeCam.transform.position
    local playerPos = playerPar.transform.position

    self.playerDis = Vector3(camPos.x - playerPos.x, camPos.y - playerPos.y, camPos.z - playerPos.z)
end

function MazeMapMgr:GetPlayerDis()
    return self.playerDis
end

---InitMap  初始化地图
function MazeMapMgr:InitMap(mapData)
    if not mapData then
        return
    end

    for k, v in pairs(mapData) do
        if checkNumber(k) > self.maxLineNum then
            self.maxLineNum = checkNumber(k)
        end
        local points = {}
        for h, j in pairs(v) do
            local point = MazeMapPointDojo.New()    
            point:FillCf(checkNumber(k), checkNumber(h), j)
            points[checkNumber(h)] = point

            if checkNumber(h) > self.maxRowNum then
                self.maxRowNum = checkNumber(h)
            end
        end
        self.map[checkNumber(k)] = points
    end
    --print(self.maxLineNum.."   "..self.maxRowNum)
end

--实例所有建筑
function MazeMapMgr:InitMapGo()
    for k ,v in pairs(self.map) do
        --[[
        for j, m in pairs(v) do
            self:InitBuildGo(m)
        end
        ]]
        for i = 1, 4 do
            self:InitBuildGo(v[checkNumber(i)], k, i)
        end
    end
end

---InitBuildGo  初始化建筑
---@param point MazeMapPointDojo
---@param line integer
---@param row integer
function MazeMapMgr:InitBuildGo(point, line, row)
    if not point then
        point = MazeMapPointDojo.New()    
        point:FillCf(checkNumber(line), checkNumber(row))
        --return
    end
    --起点和终点不实例化
    if checkNumber(point.type) == Constants.MazePointType.StartPoint or checkNumber(point.type) == Constants.MazePointType.BossBattle then
        return
    end

    if checkNumber(point.line) == 1 or checkNumber(point.line) == 17 then
        return
    end

    local loader = ResourceModule.LoadBundleSync(CfUtils.GetMazeBuildPath(point.type), nil, true)
    if loader.IsSuccess then
        -- local go = GameObject.Instantiate(loader.ResultObject, self.pointPar.transform)
        local go = loader.Instantiate(self.pointPar.transform)
        go.name = "build"..point.line..point.row
        go.transform.position = Vector3(point.pos[1], point.pos[2], point.pos[3])
        go.transform.localRotation = Vector3(0, 180 , 0)
        point.buildGo = go
    end
    loader:Release()
end

--设置当前点
---@param point MazeMapPointDojo
function MazeMapMgr:SetCurPoint(point)
    if point then
        self.lastPoint = self.curPoint
        self.curPoint = point
    end
end
