---GetPointGo  获取一个点的实例
function MazeMapMgr:GetPointGo()
    local go
    if #self.pointGoPool > 0 then
        go = self.pointGoPool[1]
        table.remove(self.pointGoPool, 1)
    else
        local loader = ResourceModule.LoadBundleSync("Prefabs/Maze/UIBuildMessage.prefab", nil, true)
        if loader.IsSuccess then
            -- go = GameObject.Instantiate(loader.ResultObject)
            go = loader.Instantiate()
        end
        loader:Release()
    end
    return go
end

---GetPoint  行和列得到一个点
---@param id integer
---@param row integer
---@return MazeMapPointDojo
function MazeMapMgr:GetPoint(line, row)
    line = checkNumber(line)
    row = checkNumber(row)

    local points = self.map[line]
    local point = points[row]
    return point
end

---GetPointByType  通过类型来找点  为起点和终点用
---@param type integer
---@return MazeMapPointDojo
function MazeMapMgr:GetPointByType(type)
    for k, v in pairs(self.map) do
        for j, r in pairs(v) do
            if checkNumber(r.type) == checkNumber(type) then
                return r
            end
        end
    end
    return nil
end

---GetNextPoints  获取下一关所有的点
function MazeMapMgr:GetNextPoints(point)
    if not point then
        return nil
    end
    local points = self.map[point.line + 1]
    if not points then
        return nil
    end

    local pointReturn = {}
    for k, v in pairs(points) do
        if checkNumber(k) - 1 == checkNumber(point.row) or checkNumber(k) + 1 == checkNumber(point.row) or checkNumber(k) == checkNumber(point.row) then
            pointReturn[k] = v
        end
    end
    return pointReturn
end

---GetPointsByLine  获取一行的所有点
---@return MazeMapPointDojo
function MazeMapMgr:GetPointsByLine(line)
    if not line then return end

    local points = self.map[line]
    if not points then
        return nil
    end

    return points
end

function MazeMapMgr:IsSamePoint(point1, point2)
    if not point1 or not point2 then return false end

    if checkNumber(point1.line) == checkNumber(point2.line) and checkNumber(point1.row) == checkNumber(point2.row) then
        return true
    end
    return false
end

---GetBuildActPos  获取建筑行动点坐标
---@param point MazeMapPointDojo
function MazeMapMgr:GetBuildActPos(point)
    if not point then return Vector3(0,0,0) end

    if not point.buildGo then
        self:InitBuildGo(point)
    end

    --起点和终点是没有实例建筑的
    if checkNumber(point.type) == Constants.MazePointType.StartPoint or checkNumber(point.type) == Constants.MazePointType.BossBattle then
        return Vector3(point.pos[1], point.pos[2], point.pos[3])
    else
        return point.buildGo.transform:Find("standingPoint").transform.position
    end
    return Vector3(0,0,0)
end

function MazeMapMgr:GetMaxLineNum()
    --跑去起点和终点  所以减2
    return checkNumber(self.maxLineNum) - 2
end

function MazeMapMgr:GetMaxRowNum()
    return checkNumber(self.maxRowNum)
end

