--[[
    @desc: 设置点的特效
    author:{author}
    time:2020-07-30 17:28:36
    --@point:
	--@isShow: 是否显示
    @return:
]]
function MazeMapMgr:SetEffectGo(point, isShow)
    if not point then
        return
    end

    --没有的话实例化
    if not point.effectGo then
        --[[
        if not point.buildGo then
            return
        end
        local effectPar = point.buildGo.transform:Find("standingPoint")
        if not effectPar then
            return
        end
        ]]
        if not self.pointPar then
            return
        end
        if IsNull(self.loaders[CfUtils.GetMazeEffectGoPath(point.type)]) then
            self.loaders[CfUtils.GetMazeEffectGoPath(point.type)] = CS.Engine.Modules.ResourceModule.LoadBundleSync(CfUtils.GetMazeEffectGoPath(point.type), nil, true)
        end
        local go
        if self.loaders[CfUtils.GetMazeEffectGoPath(point.type)].IsSuccess then
            go = CfUtils.InstantiateGo(self.loaders[CfUtils.GetMazeEffectGoPath(point.type)].ResultObject, self.pointPar)
        end

        if go then
            point.effectGo = go
            point.effectGo.transform.position = self:GetBuildActPos(point)
        end
    end
    --没实例化出来退出
    if not point.effectGo then
        return
    end

    if isShow then
        KTool.SetActive(point.effectGo, true)
    else
        KTool.SetActive(point.effectGo, false)
    end
end

---IsCurPoint  判断一个点是不是当前点
---@param point MazeMapPointDojo
function MazeMapMgr:IsCurPoint(point)
    local curPoint = self:GetCurPoint()
    if not curPoint then
        return
    end
    if point then
        if checkNumber(point.line) == curPoint.line and checkNumber(point.row) == curPoint.row then
            return true
        end
    end
    return false
end

--是否是起点
function MazeMapMgr:IsFirstPoint(point)
    if not point then
        return false
    end
        if checkNumber(point.type) == Constants.MazePointType.StartPoint then
            return true
        end
    return false
end

--当前点是否可以到达这个点
function MazeMapMgr:IsCanArrivePoint(point)
    if not point then return false end

    local points = self.map[point.line + 1]
    if not points then
        return false
    end

    local curPoint = self:GetCurPoint()
    if not curPoint then
        return false
    end

    --规则   相邻俩个点可以到达
    if point.row >= curPoint.row - 1 and point.row <= curPoint.row + 1 and point.line == curPoint.line + 1 then
        return true
    end
    return false
end

--是否是下一关的点
function MazeMapMgr:IsNextPoints(point)
    if not point then return false end
    local curPoint = self:GetCurPoint()
    if not curPoint then
        return false
    end

    if point.line == curPoint.line + 1 then
        return true
    end
    return false
end

function MazeMapMgr:Clear()
    if self.isCamMovIng then
       self.isCamMovIng = false 
    end
    if not isNull(self.loaders) then
        for k, v in pairs(self.loaders) do
            v:Release(true)
            v = nil
        end 
    end

    self.viewPoint = nil
    self:__delete()
    self.Destroy(self)
end

return MazeMapMgr
